document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){query=t.value;$('#players').innerHTML=watchCards()}if(t.id==='penalty'){penalty=Number(t.value)/100;$('#penalty-label').textContent=Math.round(penalty*100)+'%'}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='theme-team'){selectTheme(t.value);return}if(t.id==='trade-ask'){askFor(t.value,'');return}if(t.id==='trade-subject'){askFor(tradeAsk,t.value);return}if(t.id==='trade-sort'){tradeSort=t.value;prefs.tradeSort=tradeSort;tradeVisible=5;savePrefs();render();return}if(t.id==='recap-week'){recapWeek=Number(t.value);render();ensureRecap();return}if(t.id==='waiver-horizon'||t.id==='waiver-end-week'){if(t.id==='waiver-horizon')waiverHorizon=t.value;else waiverEndWeek=Number(t.value);savePrefs();render();ensureWaiverOutlook();return}if(['trade-min-gain','trade-max-gap','trade-end-week'].includes(t.id)){if(t.id==='trade-min-gain')tradeMinGain=Number(t.value);if(t.id==='trade-max-gap')tradeMaxGap=Number(t.value);if(t.id==='trade-end-week')tradeEndWeek=Number(t.value);tradeRun++;tradeSuggestions=null;tradeManual=null;savePrefs();render();if(t.id==='trade-end-week')ensureTradeOutlook();return}if(t.dataset.waiverPosition){const side=t.dataset.waiverPosition;waiverExcluded[side]=t.checked?waiverExcluded[side].filter(p=>p!==t.value):[...new Set([...waiverExcluded[side],t.value])];savePrefs();render();return}if(t.id==='waiver-upgrades-only'){waiverUpgradesOnly=t.checked;savePrefs();render();return}if(t.dataset.protectPlayer){const l=league(),key=protectionKey(l),ids=protectedPlayers(l);prefs.waiverProtected||={};prefs.waiverProtected[key]=t.checked?[...new Set([...ids,t.dataset.protectPlayer])]:ids.filter(id=>id!==t.dataset.protectPlayer);savePrefs();render();return}if(t.id==='protect-starters'||t.id==='same-position-drops'){if(t.id==='protect-starters')protectStarters=t.checked;else samePositionDrops=t.checked;savePrefs();render();return}if(t.dataset.tradePosition){const side=t.dataset.tradePosition;tradeExcluded[side]=t.checked?tradeExcluded[side].filter(p=>p!==t.value):[...new Set([...tradeExcluded[side],t.value])];prefs.tradeExcluded=tradeExcluded;savePrefs();give=tradeCandidateIds(give,data.players,tradeExcluded.give);get=tradeCandidateIds(get,data.players,tradeExcluded.get);tradeRun++;tradeSuggestions=null;tradeManual=null;render();return}if(t.id==='analysis-league'){leagueId=t.value;tradeAsk='any';tradeTarget=null;shopId='';shopResult=null;openGame=null;give=[];get=[];tradeSuggestions=null;tradeManual=null;tradeRun++;savePrefs();render();if(isTradeView())ensureTradeOutlook();if(isLeagueView())ensureLeagueSeason();if(view==='season')ensureRecap()}if(t.id==='watch-league'){watchLeague=t.value;savePrefs();render()}if(t.id==='watch-role'){watchRole=t.value;prefs.watchRole=watchRole;savePrefs();render()}if(t.id==='bench'){bench=t.checked;savePrefs();render()}if(t.id==='trade-partner'){partnerId=t.value;get=[];tradeManual=null;render()}if(t.id==='require-benefit'){requireBenefit=t.checked;tradeSuggestions=null;savePrefs();render()}if(t.id==='penalty'){savePrefs();if(tradeSuggestions)tradeSuggestions.sort((a,b)=>compareTradeIdeas(a,b,penalty));render()}if(t.dataset.trade){let list=t.dataset.trade==='give'?give:get;list=t.checked?[...list,t.value]:list.filter(id=>id!==t.value);if(t.dataset.trade==='give')give=list;else get=list;tradeManual=null}if(t.dataset.leagueToggle){const l=data.leagues.find(l=>l.league_id===t.dataset.leagueToggle);l.enabled=t.checked;watchLeague='all';tradeSuggestions=null;tradeManual=null;savePrefs();render()}if(t.id==='week'){if(serviceMode){toast('Background service follows the current NFL week.');render();return}const week=Number(t.value);if(data.demo){toast('The demo illustrates Week 2. Connect Sleeper to browse other weeks.');render();return}if(busy){toast('Wait for the current refresh to finish.');render();return}data.week=week;data.games={};data.leagues=data.leagues.map(l=>({...l,matchups:[]}));tradeSuggestions=null;tradeManual=null;await refresh(true)}});
$('#connect-form').addEventListener('submit',e=>{e.preventDefault();const u=$('#username').value.trim();if(u)connect(u)});$('#connect').addEventListener('cancel',()=>connectRun++);
setInterval(()=>{if(!document.hidden&&(!data.demo||serviceMode))refresh(true)},45000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&(!data.demo||serviceMode)&&Date.now()-data.updatedAt>45000)refresh(true)});
function rememberPage(){
 try{localStorage.setItem('sunday-page',view)}catch{}
 const url=new URL(location.href);url.searchParams.set('view',view);history.replaceState(history.state,'',url);
}
const route=new URLSearchParams(location.search);let savedPage;try{savedPage=localStorage.getItem('sunday-page')}catch{}
const pages=nav.map(([id])=>id).filter(id=>id!=='notifications');if(route.get('view')==='notifications'){location.replace('/integrations.html');await new Promise(()=>{})}
if(pages.includes(route.get('view')))view=route.get('view');else if(pages.includes(savedPage))view=savedPage;
if(route.get('league')){leagueId=route.get('league');prefs.analysisLeague=leagueId}
rememberPage();
observeScores();render();
if(serviceMode&&prefs.username){refresh(true)}else if(prefs.username){$('#username').value=prefs.username;connect(prefs.username)}else{if(isTradeView())ensureTradeOutlook();if(view==='waivers')ensureWaiverOutlook();if(view==='season')ensureSeasonPage();if(isLeagueView())ensureLeagueSeason()}
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_awaker_watchroom',description:'Read tracked fantasy players, league-specific points, and game status currently available in Awaker.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(Object.keys(input||{}).length)throw Error('This tool takes no arguments.');return {demo:data.demo,week:data.week,updatedAt:data.updatedAt,players:aggregateWatch(data.leagues,data.players,data.games).map(p=>({name:pname(p.id),number:p.player.number,team:p.player.team,status:p.game?.state||'unknown',leagues:p.appearances}))}}})}catch{}}
